class C
{

    void M1(C c1)
    {
        int x, y;
        _ = (c1?[x = y = 0]) ?? false
            ? x.ToString()
            : y.ToString(); // 1
    }

    void M2(C c1)
    {
        int x, y;
        _ = (c1?[x = y = 0]) ?? true
            ? x.ToString() // 2
            : y.ToString();
    }

    public bool this[int x] => false;
}

